const DB_KEY='forgepro_local_v1';
const defaultDB={settings:{shopName:'ورشة بو منصور للحدادة والألمنيوم واليو بي في سي',phone:'5583 0254',address:'',currency:'ر.ق',tax:0},customers:[],projects:[],quotes:[],production:[],inventory:[],purchases:[],installations:[],invoices:[],expenses:[],suppliers:[]};
let db=loadDB(),currentPage='dashboard',toastTimer;
function loadDB(){try{const saved=JSON.parse(localStorage.getItem(DB_KEY)||'{}');const out={...structuredClone(defaultDB),...saved};out.settings={...structuredClone(defaultDB.settings),...(saved.settings||{})};if(!out.settings.shopName||out.settings.shopName==='ورشة الحدادة والألمنيوم')out.settings.shopName=defaultDB.settings.shopName;if(!out.settings.phone)out.settings.phone='5583 0254';return out}catch(e){return structuredClone(defaultDB)}}
function saveDB(){localStorage.setItem(DB_KEY,JSON.stringify(db));}
function uid(prefix){return prefix+'-'+Date.now().toString().slice(-8)+'-'+Math.floor(Math.random()*90+10)}
function money(v){return (Number(v)||0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})+' '+(db.settings.currency||'ر.ق')}
function quoteNumber(v){const n=Number(v)||0;return n===0?'':n.toLocaleString('en-US',{minimumFractionDigits:0,maximumFractionDigits:2})}
function dateNow(){return new Date().toISOString().slice(0,10)}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2600)}
function pageTitle(p){return ({dashboard:'لوحة التحكم',customers:'العملاء',projects:'المشاريع والقياسات',quotes:'عروض الأسعار',production:'أوامر التصنيع',inventory:'المخزون والمواد',purchases:'المشتريات والموردون',installations:'التركيب والتسليم',invoices:'الفواتير والدفعات',expenses:'المصروفات',reports:'التقارير',settings:'الإعدادات والنسخ الاحتياطي'})[p]||'ForgePro'}
function setPage(p){currentPage=p;document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===p));document.getElementById('pageTitle').textContent=pageTitle(p);document.getElementById('sidebar').classList.remove('open');render()}
function head(title,desc,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p>${desc}</p></div><div class="head-actions">${actions}</div></div>`}
function btn(label,act,kind='btn-primary'){return `<button class="btn ${kind}" onclick="${act}">${label}</button>`}
function stat(label,value,icon,foot=''){return `<div class="stat-card"><div class="stat-top"><span>${label}</span><div class="stat-icon">${icon}</div></div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div></div>`}
function empty(text='لا توجد بيانات حتى الآن'){return `<div class="empty-state"><div class="empty-icon">◌</div>${text}</div>`}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows||''}</tbody></table></div>`}
function badge(status){let cls='';if(/مكتمل|مسدد|معتمد|مستلم/.test(status))cls='green';else if(/متأخر|ملغي|مرفوض/.test(status))cls='red';else if(/انتظار|قيد|جديد|غير مسدد/.test(status))cls='orange';else if(/جاهز/.test(status))cls='blue';return `<span class="badge ${cls}">${esc(status||'—')}</span>`}
function customerName(id){return db.customers.find(x=>x.id===id)?.name||'عميل غير محدد'}
function projectName(id){return db.projects.find(x=>x.id===id)?.name||'مشروع غير محدد'}
function render(){const el=document.getElementById('content');const map={dashboard:dashboardPage,customers:customersPage,projects:projectsPage,quotes:quotesPage,production:productionPage,inventory:inventoryPage,purchases:purchasesPage,installations:installationsPage,invoices:invoicesPage,expenses:expensesPage,reports:reportsPage,settings:settingsPage};el.innerHTML=(map[currentPage]||dashboardPage)()}
function dashboardPage(){
 const open=db.production.filter(x=>!['مكتمل','ملغي'].includes(x.status)).length, unpaid=db.invoices.reduce((s,x)=>s+Math.max(0,(+x.total||0)-(+x.paid||0)),0), stockLow=db.inventory.filter(x=>(+x.qty||0)<=(+x.min||0)).length, revenue=db.invoices.reduce((s,x)=>s+(+x.paid||0),0), expenses=db.expenses.reduce((s,x)=>s+(+x.amount||0),0);
 const recent=[...db.projects].slice(-5).reverse().map(p=>`<tr><td><span class="primary-cell">${esc(p.name)}</span><span class="sub-cell">${esc(p.code||p.id)}</span></td><td>${esc(customerName(p.customerId))}</td><td>${esc(p.type||'—')}</td><td>${badge(p.status||'جديد')}</td><td>${money(p.total)}</td></tr>`).join('');
 return head('مرحبًا بك في ForgePro','نظرة عامة على أداء الورشة وحالة المشاريع اليوم',btn('＋ مشروع جديد',"openForm('project')"))+
 `<div class="stats-grid">${stat('المبالغ المحصلة',money(revenue),'↗','إجمالي الدفعات المسجلة')}${stat('أوامر التصنيع المفتوحة',open,'⚒','تحتاج إلى متابعة')}${stat('المبالغ المستحقة',money(unpaid),'ر.ق','حسب الفواتير المسجلة')}${stat('تنبيهات المخزون',stockLow,'▥','أصناف عند الحد الأدنى أو أقل')}</div>
 <div class="dashboard-grid"><div><div class="panel"><div class="panel-head"><div><h3>أحدث المشاريع</h3><p>آخر المشاريع المسجلة في النظام</p></div>${btn('عرض الكل',"setPage('projects')",'btn-light btn-small')}</div>${recent?table(['المشروع','العميل','نوع العمل','الحالة','القيمة'],recent):empty('أضف أول مشروع لتبدأ إدارة أعمال الورشة')}</div>
 <div class="panel"><div class="panel-head"><div><h3>إجراءات سريعة</h3><p>ابدأ العمل دون التنقل بين الأقسام</p></div></div><div class="panel-body"><div class="quick-grid"><button class="quick-tile" onclick="openForm('customer')"><span>♙</span><b>إضافة عميل</b><small>تسجيل عميل جديد</small></button><button class="quick-tile" onclick="openForm('project')"><span>▤</span><b>مشروع جديد</b><small>تسجيل القياسات والتكلفة</small></button><button class="quick-tile" onclick="openForm('inventory')"><span>▥</span><b>إضافة مادة</b><small>تحديث المخزون</small></button><button class="quick-tile" onclick="openForm('quote')"><span>▧</span><b>عرض سعر</b><small>إنشاء تسعير للعميل</small></button><button class="quick-tile" onclick="openForm('production')"><span>⚒</span><b>أمر تصنيع</b><small>بدء متابعة الإنتاج</small></button><button class="quick-tile" onclick="openForm('invoice')"><span>▣</span><b>تسجيل دفعة</b><small>فاتورة أو تحصيل</small></button></div></div></div></div>
 <div><div class="panel"><div class="panel-head"><div><h3>حالة الإنتاج</h3><p>توزيع أوامر التصنيع الحالية</p></div></div><div class="panel-body">${productionBars()}</div></div><div class="panel"><div class="panel-head"><div><h3>ملخص مالي</h3><p>المبالغ المسجلة في النظام</p></div></div><div class="panel-body"><div class="bar-row"><div class="bar-meta"><span>المقبوضات</span><span>${money(revenue)}</span></div><div class="progress"><span style="width:${Math.min(100,revenue/(revenue+expenses+1)*100)}%"></span></div></div><div class="bar-row"><div class="bar-meta"><span>المصروفات</span><span>${money(expenses)}</span></div><div class="progress"><span style="width:${Math.min(100,expenses/(revenue+expenses+1)*100)}%;background:#d65353"></span></div></div><div class="bar-row"><div class="bar-meta"><span>مستحقات العملاء</span><span>${money(unpaid)}</span></div><div class="progress"><span style="width:${Math.min(100,unpaid/(revenue+unpaid+1)*100)}%;background:#477bd4"></span></div></div></div></div><div class="notice">تذكير: خذ نسخة احتياطية دورية من صفحة الإعدادات، لأن بيانات هذا الإصدار محفوظة على المتصفح والجهاز الحالي.</div></div></div>`
}
function productionBars(){if(!db.production.length)return empty('لا توجد أوامر تصنيع');const statuses=['جديد','جاهز للتصنيع','قيد التصنيع','قيد التشطيب','تحت الفحص','جاهز للتركيب','مكتمل'];return statuses.map((s,i)=>{let n=db.production.filter(x=>x.status===s).length;return `<div class="bar-row"><div class="bar-meta"><span>${s}</span><span>${n}</span></div><div class="progress"><span style="width:${n/Math.max(1,db.production.length)*100}%;background:${['#d5a04c','#477bd4','#e5a23b','#9b79ce','#2c9c80','#4d8ed8','#169b72'][i]}"></span></div></div>`}).join('')}
function customersPage(){let rows=db.customers.slice().reverse().map(c=>`<tr><td><span class="primary-cell">${esc(c.name)}</span><span class="sub-cell">${esc(c.code||'')}</span></td><td>${esc(c.phone||'—')}</td><td>${esc(c.type||'فرد')}</td><td>${esc(c.address||'—')}</td><td>${db.projects.filter(p=>p.customerId===c.id).length}</td><td>${btn('تعديل',`editItem('customer','${c.id}')`,'btn-light btn-small')} ${btn('حذف',`deleteItem('customers','${c.id}')`,'btn-danger btn-small')}</td></tr>`).join('');return head('العملاء','إدارة بيانات العملاء والمقاولين وسجل مشاريعهم',btn('＋ إضافة عميل',"openForm('customer')"))+`<div class="panel"><div class="panel-body"><div class="search-row"><input class="field search-input" placeholder="ابحث بالاسم أو الهاتف..." oninput="filterRows(this,0)"><span class="badge">${db.customers.length} عميل</span></div><div id="customerTable">${rows?table(['العميل','الهاتف','نوع العميل','العنوان','المشاريع','الإجراءات'],rows):empty('لا يوجد عملاء. أضف أول عميل.')}</div></div></div>`}
function projectsPage(){let rows=db.projects.slice().reverse().map(p=>`<tr><td><span class="primary-cell">${esc(p.name)}</span><span class="sub-cell">${esc(p.code||p.id)}</span></td><td>${esc(customerName(p.customerId))}</td><td>${esc(p.type||'—')}</td><td>${p.width&&p.height?`${p.width} × ${p.height} ${esc(p.unit||'سم')}`:'متعدد'}</td><td>${esc(p.qty||1)}</td><td>${badge(p.status||'جديد')}</td><td>${money(p.total)}</td><td>${btn('تعديل',`editItem('project','${p.id}')`,'btn-light btn-small')} ${btn('حذف',`deleteItem('projects','${p.id}')`,'btn-danger btn-small')}</td></tr>`).join('');return head('المشاريع والقياسات','تسجيل أعمال الحدادة والألمنيوم وحساب المساحات والكميات',btn('＋ مشروع جديد',"openForm('project')"))+`<div class="panel"><div class="panel-body"><div class="search-row"><input class="field search-input" placeholder="ابحث باسم المشروع أو العميل..." oninput="filterRows(this,0)"><span class="badge">${db.projects.length} مشروع</span></div>${rows?table(['المشروع','العميل','نوع العمل','المقاس','العدد','الحالة','القيمة','الإجراءات'],rows):empty('لا توجد مشاريع مسجلة بعد.')}</div></div>`}
function quotesPage(){
 const quotes=db.quotes.slice().reverse();
 const count=status=>quotes.filter(q=>(q.status||'مسودة')===status).length;
 const total=quotes.reduce((sum,q)=>sum+(Number(q.total)||0),0);
 const cards=quotes.map(q=>{
  const status=q.status||'مسودة';
  const approvalAction=status==='معتمد'?btn('إلغاء الاعتماد',`cancelQuoteApproval('${q.id}')`,'btn-light btn-small'):btn('اعتماد',`approveQuote('${q.id}')`,'btn-approve btn-small');
  const searchText=[q.code,customerName(q.customerId),q.title||'عرض سعر',status,q.date].join(' ').toLowerCase();
  return `<article class="quote-card" data-status="${esc(status)}" data-search="${esc(searchText)}">
   <div class="quote-card-top"><div><span class="quote-code">${esc(q.code||'عرض جديد')}</span><span class="quote-date">${esc(q.date||'—')}</span></div>${badge(status)}</div>
   <div class="quote-client">${esc(customerName(q.customerId))}</div>
   <div class="quote-description">${esc(q.title||'عرض سعر — تفاصيل الأعمال داخل العرض')}</div>
   <div class="quote-card-bottom"><div><small>إجمالي العرض</small><strong>${money(q.total)}</strong></div><div class="quote-card-actions">${btn('تعديل',`editItem('quote','${q.id}')`,'btn-light btn-small')} ${btn('PDF',`printQuote('${q.id}')`,'btn-light btn-small')} ${approvalAction}<button class="btn btn-danger btn-small" onclick="deleteItem('quotes','${q.id}')">حذف</button></div></div>
  </article>`;
 }).join('');
 return head('عروض الأسعار','إدارة عروضك ومتابعة حالتها والبحث عنها بسهولة',btn('＋ إنشاء عرض سعر',"openForm('quote')"))+
 `<div class="quote-summary"><div class="quote-summary-card"><span>كل العروض</span><strong>${quotes.length}</strong><small>إجمالي العروض المسجلة</small></div><div class="quote-summary-card"><span>مسودات</span><strong>${count('مسودة')}</strong><small>عروض لم تعتمد بعد</small></div><div class="quote-summary-card"><span>معتمدة</span><strong>${count('معتمد')}</strong><small>عروض تمت الموافقة عليها</small></div><div class="quote-summary-card"><span>قيمة العروض</span><strong>${money(total)}</strong><small>مجموع القيم المسجلة</small></div></div>
 <div class="panel quote-list-panel"><div class="panel-body"><div class="quote-toolbar"><div class="quote-search-wrap"><span>⌕</span><input id="quoteSearch" class="field" placeholder="ابحث برقم العرض أو اسم العميل أو الوصف..." oninput="filterQuoteCards()"></div><select id="quoteStatusFilter" class="field quote-status-filter" onchange="filterQuoteCards()"><option value="">كل الحالات</option><option>مسودة</option><option>مرسل للعميل</option><option>معتمد</option><option>مرفوض</option></select><span class="badge" id="quoteResultCount">${quotes.length} عرض</span></div>
 <div class="quote-card-grid" id="quoteCardGrid">${cards||empty('لم تنشئ عروض أسعار بعد. ابدأ بإنشاء أول عرض سعر.')}</div><div class="empty-state quote-no-results" id="quoteNoResults" hidden>لا توجد عروض مطابقة للبحث.</div></div></div>`
}
function filterQuoteCards(){const search=(document.getElementById('quoteSearch')?.value||'').trim().toLowerCase(),status=document.getElementById('quoteStatusFilter')?.value||'';const cards=[...document.querySelectorAll('.quote-card')];let shown=0;cards.forEach(card=>{const match=(!search||(card.dataset.search||'').includes(search))&&(!status||card.dataset.status===status);card.hidden=!match;if(match)shown++});const count=document.getElementById('quoteResultCount');if(count)count.textContent=`${shown} عرض`;const empty=document.getElementById('quoteNoResults');if(empty)empty.hidden=shown!==0||cards.length===0}

function productionPage(){let rows=db.production.slice().reverse().map(p=>`<tr><td><span class="primary-cell">${esc(p.code)}</span></td><td>${esc(projectName(p.projectId))}</td><td>${esc(p.stage||'تصنيع')}</td><td>${esc(p.worker||'—')}</td><td>${esc(p.due||'—')}</td><td>${badge(p.status||'جديد')}</td><td><select class="field" style="min-width:140px;padding:6px" onchange="changeStatus('production','${p.id}',this.value)">${['جديد','جاهز للتصنيع','قيد التصنيع','قيد التشطيب','تحت الفحص','جاهز للتركيب','مكتمل','ملغي'].map(s=>`<option ${s===p.status?'selected':''}>${s}</option>`).join('')}</select></td></tr>`).join('');return head('أوامر التصنيع','متابعة مراحل القص والتجميع والتشطيب والفحص',btn('＋ أمر تصنيع',"openForm('production')"))+`<div class="panel"><div class="panel-body">${rows?table(['رقم الأمر','المشروع','المرحلة','المسؤول','موعد التسليم','الحالة','تحديث الحالة'],rows):empty('لا توجد أوامر تصنيع. أنشئ أمرًا من مشروع قائم.')}</div></div>`}
function inventoryPage(){let rows=db.inventory.slice().reverse().map(i=>`<tr><td><span class="primary-cell">${esc(i.name)}</span><span class="sub-cell">${esc(i.code||'')}</span></td><td>${esc(i.category||'مواد خام')}</td><td>${esc(i.unit||'قطعة')}</td><td>${esc(i.qty)}</td><td>${esc(i.min||0)}</td><td>${money(i.cost)}</td><td>${money((+i.qty||0)*(+i.cost||0))}</td><td>${(+i.qty||0)<=(+i.min||0)?badge('مخزون منخفض'):badge('متوفر')}</td><td>${btn('تعديل',`editItem('inventory','${i.id}')`,'btn-light btn-small')} ${btn('حركة',`stockMovement('${i.id}')`,'btn-primary btn-small')}</td></tr>`).join('');return head('المخزون والمواد','إدارة القطاعات والحديد والزجاج والإكسسوارات والهالك',btn('＋ إضافة مادة',"openForm('inventory')"))+`<div class="stats-grid">${stat('عدد الأصناف',db.inventory.length,'▥')}${stat('قيمة المخزون',money(db.inventory.reduce((s,x)=>s+(+x.qty||0)*(+x.cost||0),0)),'ر.ق')}${stat('أصناف منخفضة',db.inventory.filter(x=>(+x.qty||0)<=(+x.min||0)).length,'!')}${stat('وحدات المخزون',db.inventory.reduce((s,x)=>s+(+x.qty||0),0).toLocaleString('en-US'),'▤')}</div><div class="panel"><div class="panel-body"><div class="search-row"><input class="field search-input" placeholder="ابحث عن مادة أو كود..." oninput="filterRows(this,0)"></div>${rows?table(['الصنف','الفئة','الوحدة','الكمية','حد التنبيه','تكلفة الوحدة','قيمة المخزون','الحالة','الإجراءات'],rows):empty('أضف المواد الخام والأصناف لتبدأ متابعة المخزون.')}</div></div>`}
function purchasesPage(){let rows=db.purchases.slice().reverse().map(p=>`<tr><td class="primary-cell">${esc(p.code)}</td><td>${esc(p.supplier||'—')}</td><td>${esc(p.item||'—')}</td><td>${esc(p.qty)}</td><td>${money(p.total)}</td><td>${esc(p.date||'—')}</td><td>${badge(p.status||'مستلم')}</td></tr>`).join('');return head('المشتريات والموردون','تسجيل مشتريات المواد الخام وتتبع الموردين',btn('＋ تسجيل شراء',"openForm('purchase')"))+`<div class="panel"><div class="panel-body">${rows?table(['رقم الشراء','المورد','الصنف','الكمية','الإجمالي','التاريخ','الحالة'],rows):empty('لا توجد عمليات شراء مسجلة.')}</div></div>`}
function installationsPage(){let rows=db.installations.slice().reverse().map(i=>`<tr><td class="primary-cell">${esc(i.code)}</td><td>${esc(projectName(i.projectId))}</td><td>${esc(i.location||'—')}</td><td>${esc(i.team||'—')}</td><td>${esc(i.date||'—')}</td><td>${badge(i.status||'مجدول')}</td><td>${btn('تحديث',`editItem('installation','${i.id}')`,'btn-light btn-small')}</td></tr>`).join('');return head('التركيب والتسليم','جدولة فرق التركيب وتوثيق إنجاز المشاريع في الموقع',btn('＋ موعد تركيب',"openForm('installation')"))+`<div class="panel"><div class="panel-body">${rows?table(['رقم العملية','المشروع','الموقع','الفريق','التاريخ','الحالة','الإجراءات'],rows):empty('لا توجد عمليات تركيب مجدولة.')}</div></div>`}
function invoicesPage(){let rows=db.invoices.slice().reverse().map(i=>`<tr><td class="primary-cell">${esc(i.code)}</td><td>${esc(customerName(i.customerId))}</td><td>${esc(i.date||'—')}</td><td>${money(i.total)}</td><td>${money(i.paid)}</td><td>${money(Math.max(0,(+i.total||0)-(+i.paid||0)))}</td><td>${badge((+i.paid||0)>=(+i.total||0)?'مسدد':(+i.paid||0)>0?'مدفوع جزئيًا':'غير مسدد')}</td><td>${btn('تسجيل دفعة',`payInvoice('${i.id}')`,'btn-primary btn-small')} ${btn('طباعة',`printInvoice('${i.id}')`,'btn-light btn-small')}</td></tr>`).join('');return head('الفواتير والدفعات','متابعة قيمة الفواتير والتحصيلات والأرصدة المتبقية',btn('＋ فاتورة جديدة',"openForm('invoice')"))+`<div class="panel"><div class="panel-body">${rows?table(['رقم الفاتورة','العميل','التاريخ','الإجمالي','المدفوع','المتبقي','الحالة','الإجراءات'],rows):empty('لا توجد فواتير. يمكنك تسجيل فاتورة أو دفعة.')}</div></div>`}
function expensesPage(){let rows=db.expenses.slice().reverse().map(e=>`<tr><td class="primary-cell">${esc(e.title)}</td><td>${esc(e.category||'عام')}</td><td>${money(e.amount)}</td><td>${esc(e.date||'—')}</td><td>${esc(e.note||'—')}</td><td>${btn('حذف',`deleteItem('expenses','${e.id}')`,'btn-danger btn-small')}</td></tr>`).join('');return head('المصروفات','تسجيل النفقات التشغيلية ومتابعة تكاليف الورشة',btn('＋ مصروف جديد',"openForm('expense')"))+`<div class="stats-grid">${stat('إجمالي المصروفات',money(db.expenses.reduce((s,e)=>s+(+e.amount||0),0)),'↗')}${stat('عدد القيود',db.expenses.length,'▤')}</div><div class="panel"><div class="panel-body">${rows?table(['المصروف','التصنيف','المبلغ','التاريخ','ملاحظات','الإجراءات'],rows):empty('لا توجد مصروفات مسجلة.')}</div></div>`}
function reportsPage(){let sales=db.invoices.reduce((s,x)=>s+(+x.total||0),0),paid=db.invoices.reduce((s,x)=>s+(+x.paid||0),0),cost=db.projects.reduce((s,x)=>s+(+x.cost||0),0),expenses=db.expenses.reduce((s,x)=>s+(+x.amount||0),0);return head('التقارير','ملخصات تشغيلية ومالية من البيانات المحفوظة',btn('طباعة التقرير','window.print()','btn-light'))+`<div class="stats-grid">${stat('إجمالي الفواتير',money(sales),'▣')}${stat('إجمالي المقبوضات',money(paid),'↗')}${stat('تكاليف المشاريع المسجلة',money(cost),'⚒')}${stat('المصروفات',money(expenses),'↘')}</div><div class="two-col"><div class="panel"><div class="panel-head"><h3>ملخص المشاريع</h3></div>${table(['المؤشر','القيمة'],`<tr><td>إجمالي المشاريع</td><td>${db.projects.length}</td></tr><tr><td>المشاريع المكتملة</td><td>${db.projects.filter(x=>x.status==='مكتمل').length}</td></tr><tr><td>أوامر التصنيع</td><td>${db.production.length}</td></tr><tr><td>عمليات التركيب</td><td>${db.installations.length}</td></tr>`)}</div><div class="panel"><div class="panel-head"><h3>ملخص مالي</h3></div>${table(['المؤشر','القيمة'],`<tr><td>المبالغ المستحقة</td><td>${money(Math.max(0,sales-paid))}</td></tr><tr><td>تكلفة المخزون الحالية</td><td>${money(db.inventory.reduce((s,x)=>s+(+x.qty||0)*(+x.cost||0),0))}</td></tr><tr><td>المصروفات المسجلة</td><td>${money(expenses)}</td></tr><tr><td>صافي تقديري قبل تسويات أخرى</td><td>${money(paid-expenses-cost)}</td></tr>`)}</div></div><div class="notice">التقارير تعتمد على البيانات التي أدخلتها. صافي الربح هنا تقديري، ولا يُعد قوائم مالية معتمدة.</div>`}
function settingsPage(){return head('الإعدادات والنسخ الاحتياطي','إدارة بيانات الورشة وحفظ نسخة من قاعدة البيانات')+`<div class="two-col"><div class="settings-card"><h3>بيانات الورشة</h3><p>تظهر هذه البيانات في المستندات المطبوعة.</p><form id="settingsForm" onsubmit="saveSettings(event)"><div class="form-grid"><div class="full"><label>اسم الورشة</label><input class="field" name="shopName" value="${esc(db.settings.shopName)}" required></div><div><label>رقم الهاتف</label><input class="field" name="phone" value="${esc(db.settings.phone)}"></div><div><label>العملة</label><input class="field" name="currency" value="${esc(db.settings.currency)}"></div><div class="full"><label>العنوان</label><input class="field" name="address" value="${esc(db.settings.address)}"></div><div><label>الضريبة %</label><input class="field" type="number" min="0" max="100" step=".01" name="tax" value="${esc(db.settings.tax)}"></div></div><div class="form-actions"><button class="btn btn-primary">حفظ الإعدادات</button></div></form></div><div><div class="settings-card"><h3>النسخ الاحتياطي</h3><p>صدّر كل بياناتك إلى ملف JSON، ثم احتفظ به على وحدة تخزين خارجية أو مكان آمن.</p><button class="btn btn-primary" onclick="exportBackup()">⬇ تنزيل نسخة احتياطية</button><hr style="border:0;border-top:1px solid #edf1f5;margin:18px 0"><label>استعادة نسخة احتياطية</label><input class="field" type="file" id="backupFile" accept=".json,application/json"><div class="form-actions"><button class="btn btn-light" onclick="importBackup()">استعادة البيانات</button></div></div><div class="settings-card"><h3>تصدير البيانات</h3><p>يمكنك تصدير الجداول الأساسية بصيغة CSV وفتحها في برامج الجداول.</p><button class="btn btn-light" onclick="exportCSV('customers')">تصدير العملاء CSV</button> <button class="btn btn-light" onclick="exportCSV('projects')">تصدير المشاريع CSV</button></div><div class="settings-card"><h3>إدارة البيانات</h3><p>حذف البيانات لا يمكن التراجع عنه. صدّر نسخة احتياطية قبل المتابعة.</p><button class="btn btn-danger" onclick="resetData()">إعادة ضبط جميع البيانات</button></div></div></div>`}
function options(items,selected){return `<option value="">اختر...</option>`+items.map(x=>`<option value="${esc(x.id)}" ${x.id===selected?'selected':''}>${esc(x.name||x.code||x.title)}</option>`).join('')}
const schemas={
 customer:{title:'إضافة عميل',collection:'customers',prefix:'CUS',fields:[['name','اسم العميل','text',1],['phone','رقم الهاتف','tel'],['type','نوع العميل','select',['فرد','شركة','مقاول']],['address','العنوان / موقع العمل','text'],['note','ملاحظات','textarea']]},
 project:{title:'مشروع جديد',collection:'projects',prefix:'PRJ',fields:[['name','اسم المشروع','text',1],['customerId','العميل','selectCustomers',1],['type','نوع العمل','select',['باب ألمنيوم','شبابيك ألمنيوم','واجهة زجاجية','مطبخ ألمنيوم','بوابة حديد','درابزين','مظلة','هيكل معدني','أعمال أخرى']],['width','العرض','number'],['height','الارتفاع','number'],['unit','وحدة القياس','select',['سم','مم','متر']],['qty','العدد','number',1],['unitPrice','سعر الوحدة','number'],['total','قيمة البيع','number'],['cost','التكلفة التقديرية','number'],['status','الحالة','select',['جديد','بانتظار القياسات','بانتظار موافقة العميل','قيد التصنيع','جاهز للتركيب','مكتمل']],['due','موعد التسليم','date'],['note','ملاحظات / مواصفات','textarea']]},
 quote:{title:'إنشاء عرض سعر',collection:'quotes',prefix:'QT',fields:[['customerId','العميل','selectCustomers',1],['extra','تكاليف إضافية','number'],['discount','الخصم','number'],['status','الحالة','select',['مسودة','مرسل للعميل','معتمد','مرفوض']],['note','المواصفات والشروط','textarea']]},
 production:{title:'إنشاء أمر تصنيع',collection:'production',prefix:'FAB',fields:[['projectId','المشروع','selectProjects',1],['stage','مرحلة العمل','select',['تجهيز المواد','القص','التشغيل والتخريم','التجميع','اللحام','التشطيب والدهان','تركيب الزجاج والإكسسوارات','الفحص النهائي']],['worker','الفني / المسؤول','text'],['due','موعد التسليم','date'],['status','الحالة','select',['جديد','جاهز للتصنيع','قيد التصنيع','قيد التشطيب','تحت الفحص','جاهز للتركيب','مكتمل','ملغي']],['note','ملاحظات التصنيع','textarea']]},
 inventory:{title:'إضافة مادة للمخزون',collection:'inventory',prefix:'STK',fields:[['name','اسم المادة / الصنف','text',1],['category','الفئة','select',['قطاع ألمنيوم','حديد','زجاج','إكسسوارات','مواد لحام','دهان وتشطيب','أدوات','أخرى']],['unit','الوحدة','select',['عود','متر','متر مربع','قطعة','كيلوغرام','علبة','لتر']],['qty','الكمية الحالية','number',1],['min','حد التنبيه','number'],['cost','تكلفة الوحدة','number'],['code','كود الصنف','text'],['note','موقع التخزين / ملاحظات','textarea']]},
 purchase:{title:'تسجيل عملية شراء',collection:'purchases',prefix:'PUR',fields:[['supplier','اسم المورد','text',1],['item','الصنف المشترى','text',1],['qty','الكمية','number',1],['unitCost','تكلفة الوحدة','number',1],['date','تاريخ الشراء','date'],['status','الحالة','select',['طلب شراء','مستلم','مرتجع']],['note','ملاحظات / رقم الفاتورة','textarea']]},
 installation:{title:'جدولة عملية تركيب',collection:'installations',prefix:'INS',fields:[['projectId','المشروع','selectProjects',1],['location','الموقع','text',1],['team','فريق التركيب','text'],['date','تاريخ التركيب','date',1],['status','الحالة','select',['مجدول','قيد التنفيذ','مكتمل','مؤجل']],['note','ملاحظات','textarea']]},
 invoice:{title:'إنشاء فاتورة',collection:'invoices',prefix:'INV',fields:[['customerId','العميل','selectCustomers',1],['projectId','المشروع المرتبط','selectProjects'],['title','الوصف','text',1],['total','إجمالي الفاتورة قبل الضريبة','number',1],['paid','المبلغ المدفوع','number',1],['date','تاريخ الفاتورة','date'],['note','ملاحظات','textarea']]},
 expense:{title:'تسجيل مصروف',collection:'expenses',prefix:'EXP',fields:[['title','اسم المصروف','text',1],['category','التصنيف','select',['مواد','رواتب','إيجار','نقل','كهرباء ومياه','صيانة معدات','أدوات','إداري','أخرى']],['amount','المبلغ','number',1],['date','التاريخ','date',1],['note','ملاحظات / مرجع','textarea']]}
};
function quoteWorkRow(i,old={}){const titleKey=i===1?'title':`title${i}`,qtyKey=i===1?'qty':`qty${i}`,priceKey=i===1?'unitPrice':`unitPrice${i}`;return `<div class="quote-work-row full" data-work-row="${i}"><div class="quote-work-title"><label for="${titleKey}">وصف العمل ${i}</label><textarea class="field quote-description-input" id="${titleKey}" name="${titleKey}" rows="1" oninput="this.style.height='auto';this.style.height=this.scrollHeight+'px'" ${i===1?'required':''} placeholder="اكتب وصف العمل">${esc(old[titleKey]||'')}</textarea></div><div><label for="${qtyKey}">العدد</label><input class="field" id="${qtyKey}" name="${qtyKey}" type="text" inputmode="decimal" autocomplete="off" value="${esc(old[qtyKey]??(i===1?1:''))}" ${i===1?'required':''}></div><div><label for="${priceKey}">السعر</label><input class="field" id="${priceKey}" name="${priceKey}" type="text" inputmode="decimal" autocomplete="off" value="${esc(old[priceKey]??(i===1?0:''))}" ${i===1?'required':''}></div></div>`}
function addQuoteWorkRow(){const wrap=document.getElementById('quoteWorkRows');if(!wrap)return;const next=Math.max(0,...[...wrap.querySelectorAll('[data-work-row]')].map(x=>Number(x.dataset.workRow)||0))+1;wrap.insertAdjacentHTML('beforeend',quoteWorkRow(next));}
function openForm(type,id=null){let sc=schemas[type];if(!sc)return;let old=id?db[sc.collection].find(x=>x.id===id):null;let fields=sc.fields.map(f=>{let [name,label,kind,extra]=f;let value=old?.[name]??(name==='date'?dateNow():name==='qty'?1:name==='unit'?'سم':name==='status'?(type==='project'?'جديد':type==='quote'?'مسودة':type==='production'?'جديد':type==='installation'?'مجدول':''):name==='paid'?0:'');let req=extra===1;let input='';if(kind==='selectCustomers')input=`<select class="field" name="${name}" ${req?'required':''}>${options(db.customers,value)}</select>`;else if(kind==='selectProjects')input=`<select class="field" name="${name}" ${req?'required':''}>${options(db.projects,value)}</select>`;else if(kind==='select')input=`<select class="field" name="${name}" ${req?'required':''}>${extra.map(s=>`<option ${s===value?'selected':''}>${s}</option>`).join('')}</select>`;else if(kind==='textarea')input=`<textarea class="field" rows="3" name="${name}">${esc(value)}</textarea>`;else input=`<input class="field" name="${name}" type="${kind}" value="${esc(value)}" ${req?'required':''} ${kind==='number'?'step="0.01" min="0"':''}>`;return `<div class="${kind==='textarea'?'full':''}"><label>${label}</label>${input}</div>`}).join('');if(type==='quote'){let count=1;for(let i=2;i<100;i++){if(old?.[`title${i}`]||old?.[`qty${i}`]||old?.[`unitPrice${i}`])count=i;}const rows=Array.from({length:count},(_,j)=>quoteWorkRow(j+1,old||{})).join('');const workBlock=`<div class="full quote-work-section"><div id="quoteWorkRows">${rows}</div><button class="btn btn-light quote-add-btn" type="button" onclick="addQuoteWorkRow()">＋ إضافة وصف عمل</button></div>`;const firstEnd=fields.indexOf('</div>')+6;fields=fields.slice(0,firstEnd)+workBlock+fields.slice(firstEnd);}document.getElementById('modal').innerHTML=`<div class="modal-head"><h2>${old?'تعديل':'إضافة'} ${sc.title.replace(/^(إضافة|إنشاء|تسجيل|جدولة) /,'')}</h2><button class="modal-close" onclick="closeModal()">×</button></div><form id="dataForm" onsubmit="saveForm(event,'${type}','${id||''}')"><div class="modal-body"><div class="form-grid">${fields}</div><p style="font-size:10px;color:#9aa6b1;margin:16px 0 0">* الحقول المطلوبة يجب تعبئتها قبل الحفظ.</p></div><div class="modal-footer"><button class="btn btn-primary" type="submit">حفظ البيانات</button><button class="btn btn-light" type="button" onclick="closeModal()">إلغاء</button></div></form>`;document.getElementById('modalBackdrop').classList.add('show');document.querySelectorAll('.quote-description-input').forEach(el=>{el.style.height='auto';el.style.height=el.scrollHeight+'px'})}
function closeModal(){document.getElementById('modalBackdrop').classList.remove('show')}
function parseNumeric(v){if(v===undefined||v===null)return 0;let s=String(v).trim().replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d)).replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).replace(/[٬,]/g,'').replace(/٫/g,'.').replace(/[^0-9.\-]/g,'');const n=Number(s);return Number.isFinite(n)?n:0}
function saveForm(e,type,id){e.preventDefault();const sc=schemas[type],fd=new FormData(e.target),obj={};for(const [k,v] of fd.entries())obj[k]=v.trim();for(const f of sc.fields){let k=f[0];if(f[2]==='number')obj[k]=parseNumeric(obj[k])}if(type==='project'){if(!obj.total&&obj.width&&obj.height)obj.total=(Number(obj.width)/100)*(Number(obj.height)/100)*Number(obj.qty||1)*Number(obj.unitPrice||0);if(!obj.total)obj.total=Number(obj.qty||1)*Number(obj.unitPrice||0)}if(type==='quote'){let subtotal=0;for(const k of Object.keys(obj)){const m=k.match(/^(?:qty|unitPrice)(\d*)$/);if(m){obj[k]=parseNumeric(obj[k])}}for(let i=1;i<100;i++){const titleKey=i===1?'title':`title${i}`,qtyKey=i===1?'qty':`qty${i}`,priceKey=i===1?'unitPrice':`unitPrice${i}`;if(obj[titleKey]!==undefined||obj[qtyKey]!==undefined||obj[priceKey]!==undefined)subtotal+=parseNumeric(obj[qtyKey])*parseNumeric(obj[priceKey])}obj.total=Math.max(0,subtotal+parseNumeric(obj.extra)-parseNumeric(obj.discount));obj.code=id?(db.quotes.find(x=>x.id===id)?.code):('QT-'+String(Math.max(0,...db.quotes.map(x=>Number(String(x.code||'').match(/(\d+)$/)?.[1]||0)))+1).padStart(5,'0'));obj.date=id?(db.quotes.find(x=>x.id===id)?.date||dateNow()):dateNow();if(id&&db.quotes.find(x=>x.id===id)?.status==='معتمد')obj.status='مسودة'}if(type==='purchase'){obj.total=Number(obj.qty||0)*Number(obj.unitCost||0);let item=db.inventory.find(x=>x.name===obj.item);if(obj.status==='مستلم'&&item){item.qty=Number(item.qty||0)+Number(obj.qty||0)}}if(type==='invoice'){obj.total=Number(obj.total||0)*(1+(Number(db.settings.tax||0)/100));obj.paid=Math.min(Number(obj.paid||0),obj.total);obj.code=id?(db.invoices.find(x=>x.id===id)?.code):uid('INV')}if(type==='customer')obj.code=id?(db.customers.find(x=>x.id===id)?.code):uid('CUS');if(type==='project')obj.code=id?(db.projects.find(x=>x.id===id)?.code):uid('PRJ');if(type==='production')obj.code=id?(db.production.find(x=>x.id===id)?.code):uid('FAB');if(type==='inventory')obj.code=obj.code||uid('STK');if(type==='installation')obj.code=id?(db.installations.find(x=>x.id===id)?.code):uid('INS');if(type==='purchase')obj.code=id?(db.purchases.find(x=>x.id===id)?.code):uid('PUR');obj.id=id||uid(type.toUpperCase());if(!obj.date&&['expense','invoice','purchase','installation'].includes(type))obj.date=dateNow();if(id){let ix=db[sc.collection].findIndex(x=>x.id===id);if(ix>=0)db[sc.collection][ix]={...db[sc.collection][ix],...obj}}else db[sc.collection].push(obj);saveDB();closeModal();render();toast('تم حفظ البيانات بنجاح')}
function editItem(type,id){if(type==='installation'){openForm(type,id);return}openForm(type,id)}
function deleteItem(collection,id){if(!confirm('هل أنت متأكد من حذف هذا السجل؟'))return;db[collection]=db[collection].filter(x=>x.id!==id);saveDB();render();toast('تم حذف السجل')}
function changeStatus(collection,id,status){const x=db[collection].find(x=>x.id===id);if(x){x.status=status;saveDB();toast('تم تحديث الحالة');render()}}
function filterRows(input,col){const table=input.closest('.panel').querySelector('tbody');if(!table)return;let q=input.value.toLowerCase();[...table.rows].forEach(r=>r.style.display=r.cells[col]?.innerText.toLowerCase().includes(q)?'':'none')}
function approveQuote(id){let q=db.quotes.find(x=>x.id===id);if(!q)return;if(q.status==='معتمد'){toast('عرض السعر معتمد بالفعل');return}if(!confirm('هل تريد اعتماد عرض السعر؟'))return;q.status='معتمد';if(!db.projects.some(p=>p.quoteId===id)){const firstTitle=q.title||'عمل حسب عرض السعر';db.projects.push({id:uid('PRJ'),code:uid('PRJ'),name:firstTitle,customerId:q.customerId,type:'عمل حسب عرض السعر',qty:q.qty||1,unitPrice:q.unitPrice||0,total:q.total,cost:0,status:'جديد',quoteId:id,due:''})}saveDB();render();toast('تم اعتماد العرض وإنشاء مشروع مرتبط')}
function cancelQuoteApproval(id){const q=db.quotes.find(x=>x.id===id);if(!q)return;if(q.status!=='معتمد'){toast('عرض السعر غير معتمد');return}if(!confirm('هل تريد إلغاء اعتماد عرض السعر؟ سيعود إلى حالة «مسودة».'))return;q.status='مسودة';const linked=db.projects.filter(p=>p.quoteId===id);linked.forEach(p=>{if(p.status==='جديد')p.status='ملغي'});saveDB();render();toast(linked.some(p=>p.status!=='ملغي')?'تم إلغاء اعتماد العرض؛ تُرك المشروع الذي بدأ العمل عليه دون تغيير.':'تم إلغاء اعتماد العرض وإلغاء المشروع المرتبط الذي لم يبدأ العمل عليه.')}
function stockMovement(id){let x=db.inventory.find(x=>x.id===id);if(!x)return;document.getElementById('modal').innerHTML=`<div class="modal-head"><h2>حركة مخزون — ${esc(x.name)}</h2><button class="modal-close" onclick="closeModal()">×</button></div><form onsubmit="applyStock(event,'${id}')"><div class="modal-body"><div class="form-grid"><div><label>نوع الحركة</label><select class="field" name="kind"><option value="in">إضافة كمية</option><option value="out">صرف كمية</option><option value="waste">هالك</option></select></div><div><label>الكمية</label><input class="field" type="number" min=".01" step=".01" name="qty" required></div><div class="full"><label>سبب الحركة</label><input class="field" name="note" placeholder="مثال: صرف لمشروع..."></div></div><p>الرصيد الحالي: <b>${esc(x.qty)}</b> ${esc(x.unit||'')}</p></div><div class="modal-footer"><button class="btn btn-primary">حفظ الحركة</button></div></form>`;document.getElementById('modalBackdrop').classList.add('show');document.querySelectorAll('.quote-description-input').forEach(el=>{el.style.height='auto';el.style.height=el.scrollHeight+'px'})}
function applyStock(e,id){e.preventDefault();let fd=new FormData(e.target),x=db.inventory.find(x=>x.id===id),q=Number(fd.get('qty'));if(fd.get('kind')!=='in'&&q>Number(x.qty)){toast('الكمية المصروفة أكبر من المخزون');return}x.qty=Number(x.qty)+(fd.get('kind')==='in'?q:-q);x.note=(x.note||'')+` | حركة ${fd.get('kind')} ${q}: ${fd.get('note')||''}`;saveDB();closeModal();render();toast('تم تحديث المخزون')}
function payInvoice(id){let x=db.invoices.find(x=>x.id===id);if(!x)return;let amount=prompt(`المتبقي ${money(Math.max(0,x.total-x.paid))}\nأدخل مبلغ الدفعة:`);if(amount===null)return;let n=Number(amount);if(!Number.isFinite(n)||n<=0){toast('أدخل مبلغًا صحيحًا');return}x.paid=Math.min(x.total,Number(x.paid||0)+n);saveDB();render();toast('تم تسجيل الدفعة')}
function printDoc(title,body){let w=window.open('','_blank','width=900,height=700');if(!w){toast('اسمح بالنوافذ المنبثقة للطباعة');return}w.document.write(`<html lang="ar" dir="rtl"><head><meta charset="utf-8"><title>${esc(title)}</title><style>body{font-family:Tahoma,Arial;padding:35px;color:#182633}h1{font-size:23px}table{width:100%;border-collapse:collapse;margin-top:20px}td,th{border:1px solid #ddd;padding:10px;text-align:right}th{background:#f4f6f8}.muted{color:#777;font-size:12px}.total{font-size:20px;font-weight:bold;margin-top:20px}</style></head><body><h1>${esc(db.settings.shopName)}</h1><p>${esc(db.settings.phone||'')} ${esc(db.settings.address||'')}</p><hr><h2>${esc(title)}</h2>${body}<p class="muted">تم إنشاء المستند بواسطة ForgePro</p><script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close()}
function printQuote(id){
 const q=db.quotes.find(x=>x.id===id);if(!q)return;
 const w=window.open('','_blank','width=900,height=1100');if(!w){toast('اسمح بالنوافذ المنبثقة لتصدير العرض PDF');return}
 const date=q.date||dateNow(), dateDisplay=(()=>{const m=String(date).match(/^(\d{4})[-/](\d{2})[-/](\d{2})$/);return m?`${m[1]}/${m[2]}/${m[3]}م`:`${String(date).replace(/-/g,'/')}م`})(), shop='ورشة بو منصور', fullName='للحدادة والألمنيوم واليو بي في سي';
 const qrImage='data:image/png;base64,';
 const footerImage='data:image/jpeg;base64,';
 const headerImage='data:image/jpeg;base64,';
 const maxWork=Math.max(1,...Object.keys(q).map(k=>{const m=k.match(/^title(\d*)$/);return m?(m[1]?Number(m[1]):1):0}));const quoteRows=Array.from({length:maxWork},(_,j)=>{const i=j+1,titleKey=i===1?'title':`title${i}`,qtyKey=i===1?'qty':`qty${i}`,priceKey=i===1?'unitPrice':`unitPrice${i}`;return {n:i,title:q[titleKey]||'',qty:q[qtyKey]??'',price:Number(q[priceKey]||0)}}).filter(r=>r.title||r.n===1);
 // Paginate by estimated description height, not only by a fixed row count.
 // Keep each work item together: if it will not fit in the remaining space,
 // move the complete numbered row to the next page.
 const pageGroups=[];let currentPage=[],usedHeight=0;
 const PAGE_TABLE_BUDGET=137; // mm available for table body before footer/notes
 const estimateRowHeight=(row)=>{
   const text=String(row.title||'').replace(/\\s+/g,' ').trim();
   const charsPerLine=38;
   const lines=Math.max(1,Math.ceil(text.length/charsPerLine));
   return Math.max(15,lines*7.2+8);
 };
 quoteRows.forEach(row=>{
   const h=estimateRowHeight(row);
   if(currentPage.length && (currentPage.length>=5 || usedHeight+h>PAGE_TABLE_BUDGET)){
     pageGroups.push(currentPage);currentPage=[];usedHeight=0;
   }
   currentPage.push(row);usedHeight+=h;
 });
 if(currentPage.length)pageGroups.push(currentPage);
 const pagesMarkup=pageGroups.map((group,pageIndex)=>{const isFirst=pageIndex===0,isLast=pageIndex===pageGroups.length-1;const details=group.map(r=>`<tr><td>${r.n}</td><td class="description-cell">${esc(r.title)}</td><td>${r.title&&Number(r.qty||0)!==0?esc(r.qty):''}</td><td>${r.title?quoteNumber(r.price):''}</td><td>${r.title?quoteNumber(Number(r.qty||0)*r.price):''}</td></tr>`).join('');const totalRow=isLast?`<tr><td colspan="5" style="text-align:right;font-weight:900;height:14mm;white-space:nowrap;font-size:13pt;direction:rtl;color:#74183e">إجمالي المبلغ&nbsp; ${quoteNumber(q.total)||'0'}&nbsp;ريال قطري</td></tr>`:'';return `<main class="sheet"><img class="quote-header-image" src="${headerImage}" alt="ترويسة عرض سعر ورشة بو منصور">${`<div class="meta-row"><div class="meta"><div class="date">الموافق&nbsp;&nbsp; ${esc(dateDisplay)}<div class="quote-number">رقم العرض: ${esc(q.code||'QT-00001')}</div></div></div><div class="customer">السيد / ${esc(customerName(q.customerId))}</div></div>`}${isFirst?`<div class="intro">نتقدم إليكم بعرض سعر عن الأعمال التالية:</div>`:''}<table class="quote-table"><thead><tr><th></th><th>البيان</th><th>العدد</th><th>السعر</th><th>الإجمالي</th></tr></thead><tbody>${details}${totalRow}</tbody></table>${isLast&&q.note?`<div class="note">ملاحظات / الشروط: ${esc(q.note)}</div>`:''}<div class="note">* هذا العرض ساري لمدة أسبوع واحد فقط.</div><img class="quote-footer-image" src="${footerImage}" alt="تذييل ورشة بو منصور ورمز QR ورقم الهاتف"></main>`}).join('');
 w.document.write(`<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><title>عرض سعر ${esc(q.code||'')}</title><style>
 @page{size:A4;margin:0}*{box-sizing:border-box}html,body{margin:0;padding:0;background:#fff;color:#111;font-family:Tahoma,Arial,sans-serif;-webkit-print-color-adjust:exact;print-color-adjust:exact}.sheet{width:210mm;height:297mm;min-height:297mm;margin:0 auto;padding:7mm 10mm 0;position:relative;overflow:hidden;padding-bottom:49mm;page-break-after:always;break-after:page}.quote-header-image{display:block;width:calc(100% + 20mm);height:auto;max-height:none;margin:-7mm -10mm 0;object-fit:contain;page-break-inside:avoid}
 .head{display:flex;justify-content:space-between;align-items:flex-start;gap:10mm;height:21mm;direction:ltr}.en{text-align:left;direction:ltr;color:#74183e;font-weight:900;font-size:19pt;line-height:1.12;margin:3mm 0 0 0;white-space:nowrap;order:1;letter-spacing:.1px}.en small{display:block;color:#111;font-size:10pt;margin-top:3px;font-weight:800}.ar{text-align:right;color:#74183e;font-family:"HarmonyOS Sans Naskh Arabic","Noto Naskh Arabic",Tahoma,Arial,sans-serif;font-weight:900;font-size:27pt;white-space:nowrap;margin-top:0;order:2;line-height:1.12}.ar small{display:block;color:#111;font-family:"HarmonyOS Sans Naskh Arabic","Noto Naskh Arabic",Tahoma,Arial,sans-serif;font-size:11pt;margin-top:3px;font-weight:800}.title{text-align:center;font-size:31pt;font-weight:900;line-height:1.15;margin:2mm 0 4mm}.rule{height:1.2mm;background:#74183e;margin:0 -10mm}.meta-row{display:flex;justify-content:space-between;align-items:flex-start;margin:8mm 0 0;min-height:18mm;direction:ltr}.meta{display:flex;justify-content:flex-start;align-items:flex-start;margin:0;font-size:13pt;font-weight:700;order:1}.meta .date{direction:rtl;text-align:left;width:100%}.quote-number{display:block;margin-top:2mm;font-size:12pt;font-weight:800;color:#111;direction:rtl;text-align:left}.customer{text-align:right;color:#74183e;font-size:16pt;font-weight:800;margin:0;min-height:0;direction:rtl;order:2}.intro{text-align:right;font-size:15pt;font-weight:700;margin:12mm 0 4mm}.quote-table{font-family:Tahoma,Arial,sans-serif;width:100%;border-collapse:separate;border-spacing:0;border:1.2mm solid #111;border-radius:3mm;overflow:hidden;font-size:11pt;color:#000;font-weight:700}.quote-table th,.quote-table td{font-family:inherit;color:#000;font-weight:800;border-left:.45mm solid #111;border-bottom:.45mm solid #111;padding:3.2mm 2mm;text-align:center;min-height:15mm;height:auto;vertical-align:middle;line-height:1.4}.quote-table tr{break-inside:avoid;page-break-inside:avoid}.quote-table td.description-cell{font-family:inherit;color:#000;font-weight:800;font-size:11pt;white-space:pre-wrap;overflow-wrap:anywhere;word-break:break-word;line-height:1.5;text-align:right}.quote-table th{color:#000;font-size:11pt;font-weight:900;height:13mm}.quote-table th:nth-child(2),.quote-table td:nth-child(2){text-align:right;width:52%}.quote-table tr:last-child td{border-bottom:0}.quote-table th:last-child,.quote-table td:last-child{border-left:0;width:8%}.quote-table .blank td{height:15mm}.total{text-align:left;font-weight:900;font-size:15pt;margin-top:5mm}.note{text-align:right;font-weight:800;font-size:13pt;margin-top:5mm}.quote-footer-image{position:absolute;left:0;bottom:0;width:210mm;height:auto;max-height:47.5mm;object-fit:contain;object-position:bottom center;display:block;z-index:3}.bottom{position:absolute;bottom:0;left:0;right:0;height:17mm;background:#74183e;color:white;display:flex;align-items:center;padding:0 12mm 0 43mm;direction:ltr;font-size:22pt;font-weight:900}.bottom .phone{margin-left:0}.brandfoot{position:absolute;bottom:42mm;left:53mm;right:auto;width:90mm;display:flex;justify-content:flex-start;align-items:center;gap:8mm;color:#000!important;font-family:"HarmonyOS Sans Naskh Arabic","Noto Naskh Arabic",Tahoma,Arial,sans-serif;font-size:14pt;font-weight:900;line-height:1.4;direction:ltr}.brand-name{color:#000!important;white-space:nowrap;text-align:right;direction:rtl;font-family:"HarmonyOS Sans Naskh Arabic","Noto Naskh Arabic",Tahoma,Arial,sans-serif;font-size:14pt;font-weight:900;line-height:1.4}.brand-sub{color:#000!important;font-family:"HarmonyOS Sans Naskh Arabic","Noto Naskh Arabic",Tahoma,Arial,sans-serif;font-size:12pt;font-weight:900;line-height:1.4;margin-top:2mm;white-space:nowrap;text-align:right;direction:rtl}.qrmark{position:absolute;left:9mm;bottom:7mm;width:29mm;height:29mm;object-fit:contain;object-position:center;background:#fff;border:1mm solid #74183e;padding:1mm;margin:0;outline:none;box-shadow:none;border-radius:0;box-sizing:border-box;z-index:2}.foot-en{font-size:9pt;color:#74183e;direction:ltr;text-align:left}.subtle{font-size:10pt;color:#333;font-weight:600}@media print{body{width:210mm}.sheet{margin:0;width:210mm;height:297mm;min-height:297mm;page-break-after:always;break-after:page}.sheet:last-child{page-break-after:auto;break-after:auto}}
 </style></head><body>${pagesMarkup}<script>window.onload=()=>setTimeout(()=>window.print(),350)<\/script></body></html>`);
 w.document.close();
}
function printInvoice(id){let i=db.invoices.find(x=>x.id===id);if(!i)return;printDoc('فاتورة '+i.code,`<p>العميل: ${esc(customerName(i.customerId))}</p><p>التاريخ: ${esc(i.date||dateNow())}</p><p>الوصف: ${esc(i.title||'')}</p><table><tr><th>الإجمالي</th><th>المدفوع</th><th>المتبقي</th></tr><tr><td>${money(i.total)}</td><td>${money(i.paid)}</td><td>${money(Math.max(0,i.total-i.paid))}</td></tr></table><p>${esc(i.note||'')}</p>`)}
function saveSettings(e){e.preventDefault();let fd=new FormData(e.target);db.settings={...db.settings,shopName:fd.get('shopName'),phone:fd.get('phone'),currency:fd.get('currency')||'ر.ق',address:fd.get('address'),tax:Number(fd.get('tax')||0)};saveDB();render();toast('تم حفظ إعدادات الورشة')}
function exportBackup(){let blob=new Blob([JSON.stringify(db,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='ForgePro-Backup-'+dateNow()+'.json';a.click();URL.revokeObjectURL(a.href);toast('تم تجهيز النسخة الاحتياطية')}
function importBackup(){let f=document.getElementById('backupFile').files[0];if(!f){toast('اختر ملف النسخة الاحتياطية أولًا');return}if(!confirm('ستُستبدل البيانات الحالية بمحتويات النسخة. هل تريد المتابعة؟'))return;let r=new FileReader();r.onload=()=>{try{let obj=JSON.parse(r.result);if(!obj.customers||!obj.projects)throw new Error();db={...structuredClone(defaultDB),...obj};saveDB();render();toast('تمت استعادة النسخة بنجاح')}catch(e){toast('الملف غير صالح أو ليس نسخة ForgePro')}};r.readAsText(f)}
function exportCSV(collection){let arr=db[collection]||[];if(!arr.length){toast('لا توجد بيانات للتصدير');return}let keys=[...new Set(arr.flatMap(Object.keys))],csv=[keys.join(','),...arr.map(o=>keys.map(k=>'"'+String(o[k]??'').replace(/"/g,'""')+'"').join(','))].join('\r\n');let blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8;'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`ForgePro-${collection}-${dateNow()}.csv`;a.click();URL.revokeObjectURL(a.href)}
function resetData(){if(!confirm('تحذير: سيتم حذف كل العملاء والمشاريع والفواتير والمخزون نهائيًا من هذا المتصفح. هل أنت متأكد؟'))return;if(!confirm('تأكيد أخير: هل صدّرت نسخة احتياطية؟'))return;db=structuredClone(defaultDB);saveDB();render();toast('تمت إعادة ضبط البيانات')}
document.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>setPage(b.dataset.page)));
document.getElementById('mobileMenu').addEventListener('click',()=>document.getElementById('sidebar').classList.toggle('open'));
document.getElementById('quickAdd').addEventListener('click',()=>{const map={dashboard:'project',customers:'customer',projects:'project',quotes:'quote',production:'production',inventory:'inventory',purchases:'purchase',installations:'installation',invoices:'invoice',expenses:'expense'};openForm(map[currentPage]||'project')});
document.getElementById('modalBackdrop').addEventListener('click',e=>{if(e.target.id==='modalBackdrop')closeModal()});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
render();
